{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Combines model-based and model-free stage 1 values into a single net Q-value using a weighting parameter.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseveration bonus to the stage 1 logits for the action chosen in the previous trial.",
      "params": [
        {
          "name": "p",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\nif last_action != -1:\n    stickiness[last_action] = 1.0\n    \nlogits_1 = beta_1 * q_net + p * stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free Q-value of the chosen action using the stage 2 reward prediction error.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "asymmetric_unchosen_decay",
      "title": "Asymmetric Unchosen Value Decay",
      "description": "Decays the Q-values of all unchosen actions in both stages towards 0.5.",
      "params": [
        {
          "name": "decay_unchosen",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\nq_stage1_mf[unchosen_1] += decay_unchosen * (0.5 - q_stage1_mf[unchosen_1])\n        \nfor s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == action_2[trial]):\n            q_stage2_mf[s, a] += decay_unchosen * (0.5 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    }
  ]
}
